/**
 * Expo config plugin: adds a native SwiftUI App Clip target to the iOS
 * project generated by `expo prebuild`.
 *
 * Why a plugin (and not a hand-edited Xcode project): `ios/` is gitignored
 * and regenerated from scratch by `expo prebuild` on every iOS build, so
 * anything added by hand in Xcode would be wiped on the next run. This
 * plugin re-applies the clip on every prebuild, so the target survives.
 *
 * What it adds
 * - Target `BeaTrackFamClip`, bundle ID `com.beatrackfaminc.BeaTrackFam`
 *   (App ID name in the Developer portal: "BeaTrackFam App Clip" — the App
 *   ID already exists there, verified Nov 10, 2026; use this exact ID,
 *   not a "-Clip"-suffixed guess),
 *   product type `com.apple.product-type.application.on-demand-install-capable`
 *   (a real App Clip target, not an app extension).
 * - A pure-SwiftUI clip experience (templates in `plugins/app-clip/`):
 *   it does NOT embed React Native — the full app could never fit the
 *   15 MB App Clip limit. It fetches the live storefront catalog from
 *   https://beatrackfam.info/api/catalog (with a static fallback list),
 *   highlights the product from the URL that launched the clip, and hands
 *   the shopper off to the full app (StoreKit overlay / `beatrackfam://`
 *   deep link) or the website.
 * - An "Embed App Clips" copy phase on the main `BeaTrackFam` target plus a
 *   target dependency, so archiving the `BeaTrackFam` scheme builds the clip
 *   and embeds `BeaTrackFamClip.app` inside the parent app bundle — which
 *   is what makes it ship inside the IPA.
 * - The clip target in the `BeaTrackFam` scheme's Build action.
 * - `com.apple.developer.associated-domains` (`applinks:beatrackfam.info`)
 *   on the CLIP's entitlements only (checked-in
 *   `plugins/app-clip/BeaTrackFamClip.entitlements`, copied into ios/ by
 *   this plugin on every prebuild), so the clip can be invoked from
 *   beatrackfam.info links. The parent app does NOT get
 *   `com.apple.developer.associated-appclip-app-identifiers` — see the
 *   NOTE in withAppClip below (removed in 1fb5696; the profile doesn't
 *   carry it and declaring it breaks the archive).
 *
 * The clip reuses the app's version/build number from app.json (it is NOT
 * a version bump — the numbers are only stamped into the clip's Info.plist
 * and build settings so the two stay in sync).
 *
 * Signing (manual, mirroring the Rewards/Motivation plugins): each target
 * carries its own Release provisioning profile — main app "BeaTrackFam App
 * Store", clip "BeaTrackFam App Clip" — and the iOS workflow imports the
 * distribution certificate and archives with CODE_SIGN_STYLE=Manual.
 * (Nov 10, 2026: automatic signing failed the first 14.0.0 archive — Xcode
 * picked a stale team profile without the App Clip entitlement.)
 *
 * Portal/ASC work this plugin CANNOT do (Joey must do it before the first
 * clip build succeeds — see the commit message / handoff for the steps):
 * the `com.beatrackfaminc.BeaTrackFam` App ID already exists in the portal,
 * but its App Store Connect provisioning profile must exist (or be created
 * by automatic signing on first build) and an App Clip experience must be
 * configured in App Store Connect for the invocation URL.
 *
 * NOTE (Nov 10, 2026): Joey confirmed the MAIN app's real App Store bundle
 * ID is `com.beatrackfaminc` (the portal's `com.beatrackfamofficial` App ID
 * is a leftover, not the store app) — so the clip ID above is a child of the
 * real parent, and the pairing is correct.
 */
const fs = require("fs");
const path = require("path");

const {
  createRunOncePlugin,
  withDangerousMod,
  withEntitlementsPlist,
  withXcodeProject,
} = require("@expo/config-plugins");

const CLIP_TARGET_NAME = "BeaTrackFamClip";
const CLIP_BUNDLE_ID = "com.beatrackfaminc.BeaTrackFam";
const PARENT_BUNDLE_ID = "com.beatrackfaminc";
const CLIP_DIR_NAME = "BeaTrackFamClip";
const CLIP_PRODUCT_TYPE =
  "com.apple.product-type.application.on-demand-install-capable";
const MAIN_PROFILE_NAME = "BeaTrackFam App Store";
const CLIP_PROFILE_NAME = "BeaTrackFam App Clip";

/** Copy the clip source templates into ios/BeaTrackFamClip. */
function withAppClipFiles(config) {
  return withDangerousMod(config, [
    "ios",
    async (config) => {
      const projectRoot = config.modRequest.projectRoot;
      const iosRoot = path.join(projectRoot, "ios");
      const clipDir = path.join(iosRoot, CLIP_DIR_NAME);
      const templatesDir = path.join(projectRoot, "plugins", "app-clip");

      // Templates are the source of truth; the generated copy is disposable.
      fs.rmSync(clipDir, { recursive: true, force: true });
      fs.cpSync(templatesDir, clipDir, { recursive: true });

      // Stamp the app's version/build number into the clip's Info.plist so
      // the clip ships with the same version as the parent app.
      const version = config.version || "1.0";
      const buildNumber =
        (config.ios && config.ios.buildNumber) || "1";
      const infoPlistPath = path.join(clipDir, "Info.plist");
      const infoPlist = fs
        .readFileSync(infoPlistPath, "utf8")
        .replace(/__APP_VERSION__/g, String(version))
        .replace(/__BUILD_NUMBER__/g, String(buildNumber));
      fs.writeFileSync(infoPlistPath, infoPlist);

      // App icon: reuse the app's 1024x1024 icon for the clip's AppIcon set.
      fs.copyFileSync(
        path.join(projectRoot, "assets", "icon.png"),
        path.join(clipDir, "Assets.xcassets", "AppIcon.appiconset", "AppIcon-1024.png")
      );

      return config;
    },
  ]);
}

function withAppClip(config) {
  config = withAppClipFiles(config);
  // NOTE (Nov 10, 2026): do NOT add
  // com.apple.developer.associated-appclip-app-identifiers to the parent
  // app's entitlements. The "BeaTrackFam App Store" provisioning profile
  // does not carry that entitlement (regenerating it in the portal did
  // not add it), so declaring it makes the archive fail with
  // 'Provisioning profile "BeaTrackFam App Store" doesn't match the
  // entitlements file's value...' (main runs 32 and 33). Rewards and
  // Motivation never declare it on the parent and archive fine — the
  // association is established by the clip's own
  // parent-application-identifiers entitlement plus the Embed App Clips
  // phase. If App Store Connect ever rejects the upload for a missing
  // association, that is a portal App ID fix, not a plugin one.
  config = withAppClipXcodeProject(config);
  return config;
}

function clipBuildSettings(config, isDebug) {
  const version = config.version || "1.0";
  const buildNumber = (config.ios && config.ios.buildNumber) || "1";
  const deploymentTarget =
    (config.ios && config.ios.deploymentTarget) || "16.4";

  const settings = {
    ASSETCATALOG_COMPILER_APPICON_NAME: "AppIcon",
    CLANG_ENABLE_MODULES: "YES",
    CODE_SIGN_ENTITLEMENTS: `${CLIP_DIR_NAME}/${CLIP_TARGET_NAME}.entitlements`,
    CURRENT_PROJECT_VERSION: String(buildNumber),
    INFOPLIST_FILE: `${CLIP_DIR_NAME}/Info.plist`,
    IPHONEOS_DEPLOYMENT_TARGET: String(deploymentTarget),
    LD_RUNPATH_SEARCH_PATHS: ['"$(inherited)"', '"@executable_path/Frameworks"'],
    MARKETING_VERSION: String(version),
    PRODUCT_BUNDLE_IDENTIFIER: `"${CLIP_BUNDLE_ID}"`,
    PRODUCT_NAME: `"${CLIP_TARGET_NAME}"`,
    SWIFT_VERSION: "5.0",
    // Xcode requires the clip's UIDeviceFamily to EQUAL the parent app's
    // (Universal 1,2 here) — iPhone-only '1' fails ValidateEmbeddedBinary
    // at archive (Rewards run 50, Nov 10 2026). ASC's iPad rules for a
    // universal clip are met by the clip's icon set +
    // UISupportedInterfaceOrientations~ipad + UILaunchScreen in Info.plist.
    TARGETED_DEVICE_FAMILY: '"1,2"',
    VERSIONING_SYSTEM: '"apple-generic"',
  };

  if (isDebug) {
    // Debug keeps automatic signing for local dev builds.
    settings.CODE_SIGN_STYLE = "Automatic";
    settings.GCC_PREPROCESSOR_DEFINITIONS = ['"DEBUG=1"', '"$(inherited)"'];
    settings.SWIFT_OPTIMIZATION_LEVEL = '"-Onone"';
  } else {
    // Release only: manual signing with the clip's App Store profile,
    // mirroring the Rewards/Motivation plugins.
    settings.CODE_SIGN_STYLE = "Manual";
    settings.PROVISIONING_PROFILE_SPECIFIER = `"${CLIP_PROFILE_NAME}"`;
  }

  return settings;
}

/**
 * Drop attributes the `xcode` writer would otherwise emit as literal
 * `undefined` (e.g. fileEncoding on a product ref) from a PBXFileReference.
 */
function cleanFileReference(project, fileRefUuid) {
  const ref =
    project.hash.project.objects.PBXFileReference &&
    project.hash.project.objects.PBXFileReference[fileRefUuid];
  if (!ref) return;
  for (const key of Object.keys(ref)) {
    if (ref[key] === undefined || ref[key] === "undefined") {
      delete ref[key];
    }
  }
}

/** Set the main target's Release signing to manual + the named App Store
 * profile (mirrors the Motivation plugin's setReleaseProfileSpecifier).
 * The workflow must NOT pass PROVISIONING_PROFILE_SPECIFIER on the command
 * line — it would force the main profile onto the clip target too. */
function setReleaseProfileSpecifier(project, targetUuid, profileName) {
  const target = project.pbxNativeTargetSection()[targetUuid];
  if (!target) return;
  const list = project.pbxXCConfigurationList()[target.buildConfigurationList];
  if (!list) return;
  for (const cfg of list.buildConfigurations || []) {
    const conf = project.pbxXCBuildConfigurationSection()[cfg.value];
    if (conf && conf.name === "Release") {
      conf.buildSettings.CODE_SIGN_STYLE = "Manual";
      conf.buildSettings.PROVISIONING_PROFILE_SPECIFIER = `"${profileName}"`;
    }
  }
}

/** Add the clip target, its phases/files, and the embed phase to the project. */
function withAppClipXcodeProject(config) {
  return withXcodeProject(config, (config) => {
    const project = config.modResults;
    const objects = project.hash.project.objects;

    const nativeTargets = objects.PBXNativeTarget || {};
    const alreadyAdded = Object.values(nativeTargets).some(
      (target) =>
        target &&
        typeof target.name === "string" &&
        target.name.replace(/"/g, "") === CLIP_TARGET_NAME
    );
    if (alreadyAdded) {
      return config;
    }

    const mainTarget = project.getFirstTarget();
    const mainTargetUuid = mainTarget.uuid;
    const mainTargetName = (nativeTargets[mainTargetUuid].name || "").replace(
      /"/g,
      ""
    );
    if (mainTargetName !== "BeaTrackFam") {
      // eslint-disable-next-line no-console
      console.warn(
        `[with-app-clip] First target is "${mainTargetName}", not "BeaTrackFam" — skipping App Clip target.`
      );
      return config;
    }

    // Main target: manual signing with the App Store profile (Release
    // only) — see setReleaseProfileSpecifier above.
    setReleaseProfileSpecifier(project, mainTargetUuid, MAIN_PROFILE_NAME);

    // --- Build configurations -------------------------------------------
    const configList = project.addXCConfigurationList(
      [
        {
          name: "Debug",
          isa: "XCBuildConfiguration",
          buildSettings: clipBuildSettings(config, true),
        },
        {
          name: "Release",
          isa: "XCBuildConfiguration",
          buildSettings: clipBuildSettings(config, false),
        },
      ],
      "Release",
      `Build configuration list for PBXNativeTarget "${CLIP_TARGET_NAME}"`
    );

    // --- Target ----------------------------------------------------------
    // Generate the uuid first: addProductFile needs it, and the target
    // object needs the product file's ref.
    const clipTargetUuid = project.generateUuid();
    const productFile = project.addProductFile(CLIP_TARGET_NAME, {
      target: clipTargetUuid,
      explicitFileType: '"wrapper.application"',
    });
    // Build-file comment reads "<basename> in <group>"; without this it
    // renders as "in undefined".
    productFile.group = "Products";
    project.addToPbxBuildFileSection(productFile);
    cleanFileReference(project, productFile.fileRef);

    const clipTarget = {
      uuid: clipTargetUuid,
      pbxNativeTarget: {
        isa: "PBXNativeTarget",
        buildConfigurationList: configList.uuid,
        buildPhases: [],
        buildRules: [],
        dependencies: [],
        name: `"${CLIP_TARGET_NAME}"`,
        productName: `"${CLIP_TARGET_NAME}"`,
        productReference: productFile.fileRef,
        productType: `"${CLIP_PRODUCT_TYPE}"`,
      },
    };
    project.addToPbxNativeTargetSection(clipTarget);
    project.addToPbxProjectSection(clipTarget);

    // --- Source group (ios/BeaTrackFamClip in the project navigator) -----
    const clipGroupUuid = project.generateUuid();
    objects.PBXGroup[clipGroupUuid] = {
      isa: "PBXGroup",
      children: [],
      name: CLIP_DIR_NAME,
      path: CLIP_DIR_NAME,
      sourceTree: '"<group>"',
    };
    objects.PBXGroup[`${clipGroupUuid}_comment`] = CLIP_DIR_NAME;
    const mainGroupUuid =
      project.pbxProjectSection()[project.getFirstProject().uuid].mainGroup;
    objects.PBXGroup[mainGroupUuid].children.push({
      value: clipGroupUuid,
      comment: CLIP_DIR_NAME,
    });

    // --- Build phases + files --------------------------------------------
    project.addBuildPhase([], "PBXSourcesBuildPhase", "Sources", clipTargetUuid);
    project.addBuildPhase(
      [],
      "PBXFrameworksBuildPhase",
      "Frameworks",
      clipTargetUuid
    );
    project.addBuildPhase(
      [],
      "PBXResourcesBuildPhase",
      "Resources",
      clipTargetUuid
    );

    // addSourceFile stores the full relative path, but the clip's PBXGroup
    // already carries path = BeaTrackFamClip, so the full path resolves
    // doubled (…/BeaTrackFamClip/BeaTrackFamClip/…) — same bug as the
    // xcassets ref below. Use bare basenames in this group.
    const clipSwiftFiles = [
      project.addSourceFile(`${CLIP_DIR_NAME}/AppClipApp.swift`, {
        target: clipTargetUuid,
      }, clipGroupUuid),
      project.addSourceFile(`${CLIP_DIR_NAME}/ContentView.swift`, {
        target: clipTargetUuid,
      }, clipGroupUuid),
    ];
    for (const f of clipSwiftFiles) {
      if (f && f.fileRef) {
        const ref =
          project.hash.project.objects.PBXFileReference &&
          project.hash.project.objects.PBXFileReference[f.fileRef];
        if (ref) ref.path = `"${f.basename}"`;
      }
    }
    // StoreKit is used for the "Get the full app" App Store overlay.
    const storeKitFile = project.addFramework("StoreKit.framework", {
      target: clipTargetUuid,
    });
    const assetsFile = project.addResourceFile(
      `${CLIP_DIR_NAME}/Assets.xcassets`,
      { target: clipTargetUuid },
      clipGroupUuid
    );
    // addResourceFile stores the full relative path, but the clip's
    // PBXGroup already carries path = BeaTrackFamClip, so the full path
    // resolves doubled (…/BeaTrackFamClip/BeaTrackFamClip/…) and actool
    // can't find the AppIcon set (main run 34, Nov 10 2026 — same bug as
    // Motivation's Images.xcassets). The clip's other files use bare
    // basenames in this group — match that.
    if (assetsFile && assetsFile.fileRef) {
      const assetsRef =
        project.hash.project.objects.PBXFileReference &&
        project.hash.project.objects.PBXFileReference[assetsFile.fileRef];
      if (assetsRef) assetsRef.path = '"Assets.xcassets"';
    }
    // The `xcode` writer emits literal `undefined` for unset file-ref
    // attributes (fileEncoding/lastKnownFileType on the product and
    // framework refs, explicitFileType on source refs). Xcode tolerates
    // them — Expo's own generated project has the same artifacts — but
    // strip them so the clip's refs match what Xcode itself writes.
    for (const file of [storeKitFile, assetsFile]) {
      if (file && file.fileRef) cleanFileReference(project, file.fileRef);
    }
    for (const [key, ref] of Object.entries(objects.PBXFileReference)) {
      if (
        ref &&
        typeof ref.path === "string" &&
        ref.path.includes(CLIP_DIR_NAME)
      ) {
        cleanFileReference(project, key);
      }
    }

    // --- Embed the clip in the parent app ---------------------------------
    // Main target must build the clip first, then copy BeaTrackFamClip.app
    // into the parent bundle (dstSubfolderSpec 16 = App Clips destination).
    // A fresh Expo project has no PBXTargetDependency/PBXContainerItemProxy
    // sections at all, and addTargetDependency silently no-ops without
    // them — create the sections first.
    if (!objects.PBXTargetDependency) objects.PBXTargetDependency = {};
    if (!objects.PBXContainerItemProxy) objects.PBXContainerItemProxy = {};
    project.addTargetDependency(mainTargetUuid, [clipTargetUuid]);
    const embedPhase = project.addBuildPhase(
      [`${CLIP_TARGET_NAME}.app`],
      "PBXCopyFilesBuildPhase",
      "Embed App Clips",
      mainTargetUuid,
      "watch2_app", // folder-type mapping that yields dstSubfolderSpec 16
      // Explicit destination: the dstPath "" form generated a phase that
      // Xcode never executed in the Rewards 2.0.0 archives (Nov 10, 2026 —
      // clip built, never embedded, ASC said HAS APP CLIP: NO twice). The
      // explicit $(CONTENTS_FOLDER_PATH)/AppClips destination (same as the
      // Motivation plugin) is the form that actually runs.
      '"$(CONTENTS_FOLDER_PATH)/AppClips"'
    );
    if (embedPhase && embedPhase.buildPhase) {
      embedPhase.buildPhase.dstSubfolderSpec = 16;
    }

    // --- Scheme: build the clip when archiving the parent scheme ---------
    try {
      const schemePath = path.join(
        config.modRequest.projectRoot,
        "ios",
        "BeaTrackFam.xcodeproj",
        "xcshareddata",
        "xcschemes",
        "BeaTrackFam.xcscheme"
      );
      if (fs.existsSync(schemePath)) {
        const scheme = fs.readFileSync(schemePath, "utf8");
        const entry =
          `         <BuildActionEntry\n` +
          `            buildForTesting = "YES"\n` +
          `            buildForRunning = "YES"\n` +
          `            buildForProfiling = "YES"\n` +
          `            buildForArchiving = "YES"\n` +
          `            buildForAnalyzing = "YES">\n` +
          `            <BuildableReference\n` +
          `               BuildableIdentifier = "primary"\n` +
          `               BlueprintIdentifier = "${clipTargetUuid}"\n` +
          `               BuildableName = "${CLIP_TARGET_NAME}.app"\n` +
          `               BlueprintName = "${CLIP_TARGET_NAME}"\n` +
          `               ReferencedContainer = "container:BeaTrackFam.xcodeproj">\n` +
          `            </BuildableReference>\n` +
          `         </BuildActionEntry>\n`;
        if (!scheme.includes(`BlueprintName = "${CLIP_TARGET_NAME}"`)) {
          fs.writeFileSync(
            schemePath,
            scheme.replace("</BuildActionEntries>", `${entry}      </BuildActionEntries>`)
          );
        }
      }
    } catch (error) {
      // Non-fatal: the target dependency + Embed App Clips phase are what
      // make the archive include the clip; the scheme entry is a nicety.
      // eslint-disable-next-line no-console
      console.warn(
        `[with-app-clip] Could not patch BeaTrackFam.xcscheme: ${error.message}`
      );
    }

    return config;
  });
}

module.exports = createRunOncePlugin(withAppClip, "with-app-clip");
